// =========================================================================
// MikrotikComment
// Kumpulkan SEMUA kandidat IP WAN, lalu prioritaskan:
//   1. 10.26.*        = IP internet (punya queue/comment di MikroTik)
//   2. 172.16.32.*    = IP mgmt ONT bridge & radio
//   3. lainnya
//   4. 172.16.68.0/22 = IP TR-069, cadangan paling akhir
// =========================================================================
let candidates = [];

function addIp(val) {
  if (!val) return;
  let ip = String(val).trim().split(":")[0].split("/")[0];
  if (!/^\d+\.\d+\.\d+\.\d+$/.test(ip)) return;
  if (ip === "0.0.0.0" || ip === "127.0.0.1") return;
  if (candidates.indexOf(ip) === -1) candidates.push(ip);
}

// 1. IP WAN PPPoE (TR-098)
let pppConn = declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.ExternalIPAddress", {value: 1});
for (let p of pppConn) {
  if (p.value) addIp(p.value[0]);
}

// 2. IP WAN Static / DHCP (TR-098)
let wanConn = declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANIPConnection.*.ExternalIPAddress", {value: 1});
for (let p of wanConn) {
  if (p.value) addIp(p.value[0]);
}

// 3. IP TR-181 semua interface (termasuk interface 5 & 6)
let tr181 = declare("Device.IP.Interface.*.IPv4Address.*.IPAddress", {value: 1});
for (let p of tr181) {
  if (p.value) addIp(p.value[0]);
}

// 4. Fallback ConnectionRequestURL (IP TR-069)
if (candidates.length === 0) {
  let connUrl = declare("InternetGatewayDevice.ManagementServer.ConnectionRequestURL", {value: 1});
  if (!connUrl.value || !connUrl.value[0]) {
    connUrl = declare("Device.ManagementServer.ConnectionRequestURL", {value: 1});
  }
  if (connUrl.value && connUrl.value[0]) {
    let match = connUrl.value[0].match(/https?:\/\/([^:\/]+)/);
    if (match) addIp(match[1]);
  }
}

if (candidates.length === 0) {
  return {writable: false, value: ["IP Not Found", "xsd:string"]};
}

function rank(ip) {
  if (ip.startsWith("10.26.")) return 0;
  if (ip.startsWith("172.16.32.")) return 1;
  if (/^172\.16\.(6[89]|7[01])\./.test(ip)) return 3;
  return 2;
}

candidates.sort(function (a, b) { return rank(a) - rank(b); });

// Cari comment queue /32; kandidat pertama tetap dipakai sebagai tampilan
// bila tidak ada satupun yang terdaftar di queue (mis. ONT bridge/radio)
let targetIp = candidates[0];
let comment = "";

for (let ip of candidates) {
  let c = "";
  try {
    c = ext("mikrotik", "getComment", ip);
  } catch (e) {
    c = "";
  }
  if (c && typeof c === "string" &&
      c !== "IP Tidak Ada di Queue" && c !== "Comment Kosong" && c !== "IP Not Found" &&
      c !== "Format Queue Invalid" && c !== "JSON Parse Error" &&
      !c.startsWith("Error") && !c.startsWith("HTTP") && !c.startsWith("MikroTik")) {
    comment = c;
    targetIp = ip;
    break;
  }
}

// =========================================================================
// ISOLASI TRY-CATCH UNTUK TAG
// =========================================================================
if (comment) {
  try {
    let cleanTagName = comment.replace(/[\/\s\(\)\.\,\\]+/g, "_").replace(/[^a-zA-Z0-9_\-]/g, "");
    if (cleanTagName) {
      declare("Tags." + cleanTagName, null, {value: true});
    }
  } catch (err) {
    // Biarkan kosong jika penambahan tag gagal
  }

  return {writable: false, value: [comment, "xsd:string"]};
}

return {writable: false, value: [targetIp, "xsd:string"]};

// RSSI tiap klien WiFi yang ter-asosiasi pada ONT.
// Sumber 1: TR-069  X_HW_RSSI (firmware baru) -> SignalStrength (TR-098)
// Sumber 2: web API boaform ONT via ext("ont_wifi","get",ip) untuk firmware lama
//           yang tidak mengekspos RSSI sama sekali lewat TR-069.
// Nama klien diambil dari tabel hosts TR-069: LANDevice.1.Hosts.Host.*.HostName
// Output: "OPPO-A98-5G (192.168.1.3):-28 dBm, 192.168.1.11:-33 dBm" (terburuk lebih dulu)
const now = Date.now();

function attrs(entry) {
  return Array.isArray(entry) ? entry[1] : entry;
}

function entryPath(entry) {
  return Array.isArray(entry) ? entry[0] || "" : entry.path || "";
}

function entryValue(entry) {
  const a = attrs(entry);
  if (!a || a.value == null) return null;
  const v = Array.isArray(a.value) ? a.value[0] : a.value;
  return Array.isArray(v) ? v[0] : v;
}

function declareList(path) {
  const res = [];
  const d = declare(path, { value: now });
  if (!d || !d.size) return res;
  for (const entry of d) {
    const value = entryValue(entry);
    if (value == null || value === "") continue;
    const path2 = entryPath(entry);
    res.push({ path: path2, inst: path2.replace(/\.[^.]*$/, ""), value: value });
  }
  return res;
}

const normMac = (v) => String(v).toUpperCase().replace(/[^0-9A-F]/g, "");

const WLAN = "InternetGatewayDevice.LANDevice.*.WLANConfiguration.*.AssociatedDevice.*.";
const readClients = (paramName) => declareList(WLAN + paramName);

function result(text) {
  return { writable: false, value: [text, "xsd:string"] };
}

// Instansi AssociatedDevice -> label IP (fallback: MAC)
function labelsByInst(candidates) {
  const m = new Map();
  for (const p of candidates) {
    for (const c of readClients(p)) {
      if (!c.inst || m.has(c.inst)) continue;
      const v = String(c.value).trim();
      if (v && v !== "0.0.0.0") m.set(c.inst, v);
    }
  }
  return m;
}

// HostName klien LAN dari tabel hosts, diindex per IP dan per MAC.
function hostIndex() {
  const H = "InternetGatewayDevice.LANDevice.*.Hosts.Host.*.";
  const nameByInst = new Map();
  for (const e of declareList(H + "HostName")) {
    const nm = String(e.value).trim();
    if (nm) nameByInst.set(e.inst, nm);
  }
  const byIp = new Map();
  const byMac = new Map();
  for (const e of declareList(H + "IPAddress")) {
    const nm = nameByInst.get(e.inst);
    if (nm) byIp.set(String(e.value).trim(), nm);
  }
  for (const e of declareList(H + "MACAddress")) {
    const nm = nameByInst.get(e.inst);
    if (nm) byMac.set(normMac(e.value), nm);
  }
  return { byIp: byIp, byMac: byMac };
}

// Jadi "HostName (ip)" bila hostname diketahui; label bisa IP atau MAC.
function named(label, hosts) {
  const s = String(label || "").trim();
  if (!s) return "";
  const nm = hosts.byIp.get(s) || (s.indexOf(":") >= 0 ? hosts.byMac.get(normMac(s)) : null);
  return nm ? nm + " (" + s + ")" : s;
}

// ---------- 1. lewat TR-069 ----------
let clients = readClients("X_HW_RSSI");
if (!clients.length) clients = readClients("SignalStrength");

const rows = [];
for (const c of clients) {
  const rssi = Number(c.value);
  if (!isFinite(rssi) || rssi === 0) continue; // 0 dBm biasanya berarti tidak didukung
  rows.push({ inst: c.inst, rssi: rssi });
}

if (rows.length) {
  let labels = labelsByInst(["AssociatedDeviceIPAddress", "IPAddress"]);
  if (!labels.size) labels = labelsByInst(["AssociatedDeviceMACAddress", "MACAddress"]);
  const hosts = hostIndex();
  rows.sort((a, b) => a.rssi - b.rssi);
  return result(
    rows
      .map((r, i) => {
        const who = named(labels.get(r.inst), hosts) || "klien" + (i + 1);
        return who + ":" + r.rssi + " dBm";
      })
      .join(", ")
  );
}

// ---------- 2. fallback: scrape web API ONT ----------
// IP manajemen diambil dari koneksi WAN; yang bertanda TR069 dicoba lebih dulu.
function wanCandidates() {
  const ips = declareList(
    "InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANIPConnection.*.ExternalIPAddress"
  );
  if (!ips.length) return [];
  const svc = new Map();
  for (const c of declareList(
    "InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANIPConnection.*.X_CT-COM_ServiceList"
  )) {
    svc.set(c.inst, String(c.value).toUpperCase());
  }
  const out = [];
  for (const c of ips) {
    const ip = String(c.value).trim();
    if (!ip || ip === "0.0.0.0" || ip === "N/A") continue;
    out.push({ ip: ip, tr069: (svc.get(c.inst) || "").indexOf("TR069") >= 0 });
  }
  out.sort((a, b) => (a.tr069 === b.tr069 ? 0 : a.tr069 ? -1 : 1));
  // Maksimal 2 kandidat agar total waktu tetap di bawah EXT_TIMEOUT (3000 ms)
  return out.slice(0, 2);
}

// MAC -> IP klien dari cache TR-069, biar labelnya IP dan bukan MAC acak
function macToIp() {
  const ipByInst = labelsByInst(["AssociatedDeviceIPAddress"]);
  const m = new Map();
  for (const c of readClients("AssociatedDeviceMACAddress")) {
    const ip = ipByInst.get(c.inst);
    if (ip) m.set(normMac(c.value), ip);
  }
  return m;
}

let scraped = null;
let lastErr = null;
for (const cand of wanCandidates()) {
  try {
    const raw = ext("ont_wifi", "get", cand.ip, 1200);
    if (raw) {
      scraped = JSON.parse(raw);
      if (scraped.length) break;
    }
  } catch (err) {
    lastErr = err;
  }
}

if (!scraped || !scraped.length) {
  // Bedakan "memang tidak ada klien" dengan "klien ada tapi RSSI tidak terbaca"
  let total = 0;
  for (const c of declareList(
    "InternetGatewayDevice.LANDevice.*.WLANConfiguration.*.TotalAssociations"
  )) {
    const v = Number(c.value);
    if (isFinite(v)) total += v;
  }
  let msg = total > 0 ? "RSSI tidak tersedia (" + total + " klien)" : "tidak ada klien";
  msg += lastErr ? " [ext: " + (lastErr.message || lastErr) + "]" : " [IP ONT tidak diketahui]";
  return result(msg);
}

const byMac = macToIp();
const hosts = hostIndex();
const out = [];
for (const c of scraped) {
  const rssi = Number(c.rssi);
  if (!isFinite(rssi) || rssi === 0) continue;
  const mac = normMac(c.mac);
  const label = byMac.get(mac) || String(c.ip || "").trim() || c.mac;
  out.push({ who: named(label, hosts), rssi: rssi });
}
out.sort((a, b) => a.rssi - b.rssi);
return result(
  out.map((r, i) => (r.who || "klien" + (i + 1)) + ":" + r.rssi + " dBm").join(", ")
);

// RXPower Presisi
let now = Date.now();
let rxValue = "N/A";

// Fungsi pembaca parameter presisi dengan wildcard index (.*.)
function getValue(pathList) {
  for (let p of pathList) {
    let d = declare(p, {value: now});
    if (d && d.size) {
      for (let item of d) {
        let raw = item.value ? (Array.isArray(item.value) ? item.value[0] : item.value) : null;
        if (raw !== undefined && raw !== null && raw !== "") {
          let num = Number(raw);
          if (!isNaN(num) && num !== 0) return num;
        }
      }
    }
  }
  return null;
}

// =========================================================================
// 1. PARAMETER SESUAI DAFTAR PERSIS DARI CATATAN ANDA
// =========================================================================

// EPON RX (clink, H1s-3, VsolEpon & zimmlink)
let eponRx = getValue([
  "InternetGatewayDevice.WANDevice.*.X_CT-COM_EponInterfaceConfig.RXPower",  // clink, VsolEpon & zimmlink
  "InternetGatewayDevice.WANDevice.*.X_CMCC_EponInterfaceConfig.RXPower"   // H1s-3
]);

// GPON RX (hsgq, Huawei, VsolGpon)
let gponRx = getValue([
  "InternetGatewayDevice.WANDevice.*.X_GponInterafceConfig.RXPower",       // hsgq & Huawei (typo 'Interafce')
  "InternetGatewayDevice.WANDevice.*.X_CT-COM_GponInterfaceConfig.RXPower"  // VsolGpon
]);

// Backup EPON TX
let eponTx = getValue([
  "InternetGatewayDevice.WANDevice.*.X_CT-COM_EponInterfaceConfig.TXPower"
]);

let calcVal = null;
let num = eponRx !== null ? eponRx : gponRx;

// =========================================================================
// 2. KALKULASI LOGIKA PRESISI
// =========================================================================

// PRIORITAS 1: Jika modem langsung mengirim angka minus (-19, -16)
if (num !== null && num < 0 && num > -100) {
  calcVal = num;
}
// PRIORITAS 2: Mentah positif ratusan (V-SOL EPON/GPON, H1s-3 seperti 336)
else if (eponRx !== null && eponRx >= 5 && eponRx <= 999) {
  calcVal = 10 * Math.log10(eponRx / 1000) - 10.0;
}
else if (gponRx !== null && gponRx >= 5 && gponRx <= 999) {
  calcVal = 10 * Math.log10(gponRx / 1000) - 9.0;
}
// PRIORITAS 3: Format Ribuan / Puluhan Ribu (HSGQ, Huawei, dll)
else if (num !== null) {
  if (num <= -5000 && num >= -40000) {
    calcVal = num / 1000;
  }
  else if (num >= 5000 && num <= 40000) {
    calcVal = -num / 1000;
  }
  else if (num <= -1000 && num >= -5000) {
    calcVal = num / 100;
  }
  else if (num >= 1000 && num <= 5000) {
    calcVal = -num / 100;
  }
  else if (num >= 10000 && num <= 30000) {
    calcVal = 10 * Math.log10(num / 10000) - 25.4;
  }
  else if (num > 30000) {
    calcVal = (num - 65536) / 100;
  }
}
// PRIORITAS 4: Backup mentah TX
else if (eponTx !== null && eponTx >= 10000 && eponTx <= 30000) {
  calcVal = 10 * Math.log10(eponTx / 10000) - 25.4;
}

// Format hasil akhir
if (calcVal !== null && calcVal <= -5 && calcVal >= -38) {
  rxValue = calcVal.toFixed(2) + " dBm";
}

return {
  writable: false, 
  value: [rxValue, "xsd:string"]
};

// VP writable: Password superadmin.
// Satu parameter untuk 4 firmware; lihat komentar generator. ext() sengaja tidak
// dibungkus try/catch: ia melempar simbol agar sesi di-restart.
const now = Date.now();

const pc = declare("InternetGatewayDevice.DeviceInfo.ProductClass", { value: now });
const model = pc && pc.value ? String(pc.value[0]) : "";
if (["V2801RGW", "CL601", "ZL-4224X", "ZL-2113X", "V2802DAC"].indexOf(model) < 0)
  return { writable: false, value: ["[hanya V2801RGW, CL601, ZL-4224X, ZL-2113X, V2802DAC]", "xsd:string"] };

const url = declare("VirtualParameters.IPTR069", { value: now });
const ip = url && url.value && url.value[0]
  ? String(url.value[0]).replace(/^https?:\/\//, "").replace(/\/.*$/, "")
  : "";
const ipOk = /^[0-9.]+$/.test(ip);

const set = args && args[1] && args[1].value ? String(args[1].value[0]).trim() : null;

// Nilai yang dikembalikan beda dari yang diminta membuat GenieACS loop commit
// (fault too_many_commits), jadi penolakan dilakukan dengan melempar error.

if (model === "ZL-4224X" || model === "ZL-2113X") {
  // Akun web ONT ini tidak muncul di TR-069 kecuali sebagai teks di dalam blob
  // DeviceConfig.ConfigFile, dan menulis balik blob membuat ONT LANGSUNG REBOOT.
  // Itu harga yang diterima: jalur form Boa (/cgi-bin/mag-account.asp) ternyata
  // tidak menerapkan perubahan nama akun meski membalas signal="1".
  const CF = "InternetGatewayDevice.DeviceConfig.ConfigFile";
  const cf = declare(CF, { value: now });
  const blob = cf && cf.value ? String(cf.value[0]) : "";
  if (blob.length < 100)
    return { writable: true, value: ["[ConfigFile belum terbaca dari ONT]", "xsd:string"] };

  const a = blob.indexOf("<Account>");
  const b = blob.indexOf("</Account>");
  if (a < 0 || b <= a)
    return { writable: true, value: ["[blok <Account> tidak ada di ConfigFile]", "xsd:string"] };
  const region = blob.slice(a, b);
  const attrName = "pass" === "user" ? "username" : "web_passwd";
  const attr = (tok) => { const m = tok.match(new RegExp(attrName + '="([^"]*)"')); return m ? m[1] : ""; };
  const tgtTok = /<Entry0\b[^>]*\/>/.exec(region);
  if (!tgtTok)
    return { writable: true, value: ["[Entri akun tidak ada di ConfigFile]", "xsd:string"] };

  const cur = attr(tgtTok[0]);
  if (set != null && set.length) {
    if (!/^[A-Za-z0-9!@#$%^_+=.:,?~\-]{1,64}$/.test(set))
      throw new Error("Password superadmin memakai karakter yang tidak sah di ONT ini");
    if (set.length > 31)
      throw new Error("Password superadmin panjangnya " + set.length + "; ONT ini menolak password di atas 31 karakter");
    // Replacement berupa fungsi: $ di password punya arti khusus di string pengganti replace().
    const newTok = tgtTok[0].replace(new RegExp(attrName + '="[^"]*"'), () => attrName + '="' + set + '"');
    if (newTok === tgtTok[0])
      throw new Error("atribut " + attrName + " tidak ditemukan di entri akun target");
    const at = a + tgtTok.index;
    declare(CF, null, { value: [blob.slice(0, at) + newTok + blob.slice(at + tgtTok[0].length), "xsd:string"] });
    commit();
    return { writable: true, value: [set, "xsd:string"] };
  }

  if (!cur.length) return { writable: true, value: ["[Password superadmin tidak terbaca]", "xsd:string"] };
  return { writable: true, value: [cur, "xsd:string"] };
}

if (model === "CL601") {
  if (!ipOk) return { writable: true, value: ["[IP ONT tidak diketahui]", "xsd:string"] };
