    return { writable: true, value: ["[respon ext tidak valid]", "xsd:string"] };
  }
  const valZ = z && z["super"] ? String(z["super"]["pass"] || "") : "";
  if (!valZ.length) return { writable: true, value: ["[Password superadmin tidak terbaca]", "xsd:string"] };
  return { writable: true, value: [valZ, "xsd:string"] };
}

if (model === "V2802DAC") {
  // Akun web V2802DAC tidak diekspos lewat TR-069; nilainya ada di running-config
