// Daftar client yang AKTIF di LAN ONT (DHCP maupun IP statik).
// Sumber: tabel ARP kernel ONT via telnet ext("ont_arp","get",ip) — entri ARP
// hanya bertahan bila ada lalu-lintas paket, jadi lebih akurat daripada
// Hosts.Host (lease basi / IP statik tak tercatat).
// Nama host ditempel dari Hosts.Host bila tersedia (sekadar label).

const now = Date.now();

function attrs(entry) {
  return Array.isArray(entry) ? entry[1] : entry;
}
function entryPath(entry) {
  return Array.isArray(entry) ? entry[0] || "" : entry.path || "";
}
function entryValue(entry) {
  const a = attrs(entry);
  if (!a || a.value == null) return null;
  const v = Array.isArray(a.value) ? a.value[0] : a.value;
  return Array.isArray(v) ? v[0] : v;
}
function declareList(path) {
  const res = [];
  const d = declare(path, { value: now });
  if (!d || !d.size) return res;
  for (const entry of d) {
    const value = entryValue(entry);
    if (value == null || value === "") continue;
    res.push({ path: entryPath(entry), value: String(value).trim() });
  }
  return res;
}

function result(text) {
  return { writable: false, value: [text, "xsd:string"] };
}

// VP ini khusus GS3101 (busybox) + VSOL V2801RGW/V2802DAC (CLI "show arp").
// ONT lain tidak punya shell yang sama -> kembalikan "-" tanpa menyentuh ext().
let productClass = "";
for (const e of declareList("InternetGatewayDevice.DeviceInfo.ProductClass")) productClass = e.value;
if (!productClass)
  for (const e of declareList("DeviceInfo.ProductClass")) productClass = e.value;
if (productClass !== "GS3101" && productClass !== "V2801RGW" && productClass !== "V2802DAC") return result("-");

// IP manajemen ONT = host ConnectionRequestURL (jalur TR-069; telnet port 23 aktif di sana)
let ontIp = "";
for (const e of declareList("InternetGatewayDevice.ManagementServer.ConnectionRequestURL")) {
  const m = e.value.match(/https?:\/\/([^:\/]+)/);
  if (m) ontIp = m[1];
}
if (!ontIp) {
  for (const e of declareList("Device.ManagementServer.ConnectionRequestURL")) {
    const m = e.value.match(/https?:\/\/([^:\/]+)/);
    if (m) ontIp = m[1];
  }
}
if (!ontIp) return result("-");

// Label nama dari Hosts.Host (indeks per-instance)
const normMac = (v) => String(v).toUpperCase().replace(/[^0-9A-F]/g, "");
const instOf = (p) => p.replace(/\.[^.]*$/, "");

const nameByInst = {};
for (const e of declareList("InternetGatewayDevice.LANDevice.*.Hosts.Host.*.HostName")) {
  if (e.value) nameByInst[instOf(e.path)] = e.value;
}
const nameByIp = {};
const nameByMac = {};
for (const e of declareList("InternetGatewayDevice.LANDevice.*.Hosts.Host.*.IPAddress")) {
  const nm = nameByInst[instOf(e.path)];
  if (nm) nameByIp[e.value] = nm;
}
for (const e of declareList("InternetGatewayDevice.LANDevice.*.Hosts.Host.*.MACAddress")) {
  const nm = nameByInst[instOf(e.path)];
  if (nm) nameByMac[normMac(e.value)] = nm;
}

// ext() pakai sentinel lempar-objek utk jeda-lanjut script; TIDAK boleh dlm try/catch.
// Kalau ONT mati, ext() melempar fault dan nilai VP tampil sbg error -- itu memang perilaku GenieACS.
const raw = ext("ont_arp", "get", ontIp, 6000, productClass) || "";

let data;
try {
  data = JSON.parse(raw);
} catch (e) {
  return result("Format ARP tidak dikenali");
}

const clients = (data && data.clients) || [];
const bridge = (data && data.bridge) || [];

// Sumber status klien, dari yang paling tegas ke yang paling longgar:
//   ARP   = ada lalu-lintas IP terakhir dengan ONT (kabel & statik tercakup)
//   WiFi  = stasiun yang SAAT INI ter-asosiasi di radio (tak bergantung trafik)
//   bridge= MAC yang belajar dari trafik bridged (aging 300s) -> klien kabel yang
//           diam, yang sudah hilang dari ARP, tetap kelihatan di sini
const wbase = "InternetGatewayDevice.LANDevice.1.WLANConfiguration.";
const assocIp = {};
const assocMac = {};
for (const e of declareList(wbase + "*.AssociatedDevice.*.AssociatedDeviceIPAddress"))
  assocIp[e.value] = true;
for (const e of declareList(wbase + "*.AssociatedDevice.*.AssociatedDeviceMACAddress"))
  assocMac[normMac(e.value)] = true;

const arpByIp = {};
const arpByMac = {};
for (const c of clients) {
  arpByIp[c.ip] = c;
  arpByMac[normMac(c.mac)] = c;
}

const seen = {};
const seenMac = {};
const parts = [];
let n = 0;
const labelOf = (ip, mac) => (nameByIp[ip] || nameByMac[normMac(mac || "")] || "tanpa-nama");

for (const c of clients) {
  if (seen[c.ip]) continue;
  seen[c.ip] = true;
  seenMac[normMac(c.mac)] = true;
  const wifi = assocIp[c.ip] || assocMac[normMac(c.mac)];
  parts.push(++n + ". " + labelOf(c.ip, c.mac) + " (" + c.ip + ")" + (wifi ? "" : "*"));
}

for (const b of bridge) {
  const mac = normMac(b.mac);
  if (!mac || seenMac[mac] || arpByMac[mac] || assocMac[mac]) continue;
  seenMac[mac] = true;
  parts.push(++n + ". " + labelOf("", b.mac) + " (" + b.mac + " bridge)");
}

for (const ip of Object.keys(assocIp)) {
  if (!ip || ip === "0.0.0.0" || seen[ip] || arpByIp[ip]) continue;
  seen[ip] = true;
  parts.push(++n + ". " + labelOf(ip, "") + " (" + ip + ") idle");
}
if (!n) return result("0 Client Active");
return result(n + " Client Active: " + parts.join(", "));

