let productClass = "";
for (const e of declareList("InternetGatewayDevice.DeviceInfo.ProductClass")) productClass = e.value;
if (productClass !== "V2801RGW" && productClass !== "V2802DAC") return result("-");

const base = "InternetGatewayDevice.LANDevice.1.WLANConfiguration.";
const idxOf = (p) => {
  const m = p.match(/WLANConfiguration\.(\d+)\./);
  return m ? m[1] : "";
};
const ssid = {}, status = {}, counts = {};
for (const e of declareList(base + "*.SSID")) ssid[idxOf(e.path)] = e.value;
